def simP(Kpll,Kp,d):
    t=d.time_s.values; dt=t[1]-t[0]; th=d.bus_angle_rad.values
    ti=0.0; P0=d.active_power_pu.values[0]; Pm=np.empty(len(t))
    for k in range(len(t)):
        w=Kpll*(th[k]-ti); Pm[k]=P0-Kp*w; ti+=dt*w
    return Pm
def simQ(p,d,kind):
    t=d.time_s.values; dt=t[1]-t[0]
    V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; Q0=d.reactive_power_pu.values[0]; V0=V[0]
    Qm=np.empty(len(t)); x=0.0; Vf=V0
    for k in range(len(t)):
        if kind=='lag':
            Ka,Tq=p; Qm[k]=Q0+x; x+=dt*(Ka*(Vs[k]-V[k])-x)/Tq
        elif kind=='direct':
            Ka,=p; Qm[k]=Q0+Ka*(Vs[k]-V[k])
        elif kind=='direct+filt':
            Ka,Kb,Tv=p; Qm[k]=Q0+Ka*(Vs[k]-V[k])+Kb*(Vs[k]-Vf) ; Vf+=dt*(V[k]-Vf)/Tv
        elif kind=='lag+direct':
            Ka,Kb,Tq=p; Qm[k]=Q0+Kb*(Vs[k]-V[k])+x; x+=dt*(Ka*(Vs[k]-V[k])-x)/Tq
    return Qm
