import pandas as pd,numpy as np
from scipy.optimize import least_squares
from scipy.signal import lfilter
files=['train/A_amb_op1.csv','train/A_vref_op1.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_line_op3.csv','train/A_vref_op3.csv','train/A_amb_op2.csv']
D=[pd.read_csv(f) for f in files]
def filt(x,T,dt,x0):
    a=dt/T; y,_=lfilter([a],[1,-(1-a)],x,zi=[(1-a)*x0]); return y  # y[k]=state after input k
def simQ(p,d):
    a,b,c,T1,T2=p
    dt=d.time_s.values[1]-d.time_s.values[0]
    V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; Q0=d.reactive_power_pu.values[0]; V0=V[0]
    x1=np.concatenate([[V0],filt(V,T1,dt,V0)[:-1]]); x2=np.concatenate([[V0],filt(V,T2,dt,V0)[:-1]])
    return Q0+a*(Vs-V)+b*(V-x1)+c*(V-x2)
def res(p): return np.concatenate([simQ(p,d)-d.reactive_power_pu.values for d in D])
best=None
for T1,T2 in [(0.05,2),(0.02,0.5),(0.1,5),(0.01,1)]:
    f=least_squares(res,[1.0,0.5,0.5,T1,T2],bounds=([-50,-50,-50,1e-3,1e-3],[50,50,50,200,200]))
    if best is None or f.cost<best.cost: best=f
print(best.x.round(4), np.sqrt(np.mean(best.fun**2)).round(5))
for fn,d in zip(files,D): print(fn,np.sqrt(np.mean((simQ(best.x,d)-d.reactive_power_pu.values)**2)).round(5))

